89: Billiard_closesocket(PyObject *self, PyObject *args)
90: {
91:     HANDLE handle;
92:     int ret;
93: 
94:     if (!PyArg_ParseTuple(args, F_HANDLE ":closesocket" , &handle))
95:         return NULL;
96: 
97:     Py_BEGIN_ALLOW_THREADS
98:     ret = closesocket((SOCKET) handle);
99:     Py_END_ALLOW_THREADS
100: 
101:     if (ret)
102:         return PyErr_SetExcFromWindowsErr(PyExc_IOError, WSAGetLastError());
103:     Py_RETURN_NONE;
104: }
