106: static PyObject *
107: Billiard_recv(PyObject *self, PyObject *args)
108: {
109:     HANDLE handle;
110:     int size, nread;
111:     PyObject *buf;
112: 
113:     if (!PyArg_ParseTuple(args, F_HANDLE "i:recv" , &handle, &size))
114:         return NULL;
115: 
116:     buf = PyBytes_FromStringAndSize(NULL, size);
117:     if (!buf)
118:         return NULL;
119: 
120:     Py_BEGIN_ALLOW_THREADS
121:     nread = recv((SOCKET) handle, PyBytes_AS_STRING(buf), size, 0);
122:     Py_END_ALLOW_THREADS
123: 
124:     if (nread < 0) {
125:         Py_DECREF(buf);
126:         return PyErr_SetExcFromWindowsErr(PyExc_IOError, WSAGetLastError());
127:     }
128:     _PyBytes_Resize(&buf, nread);
129:     return buf;
130: }
